def gen(rng):
    def fmt(k, a):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))

    tests = [
        fmt(1, [0]), fmt(1, [1]), fmt(1, [10**8]), fmt(2, [0, 1, 2, 4]),
        fmt(3, [5, 6, 9, 8, 17]), fmt(4, [5, 3, 6, 12, 10]),
        fmt(3, [7, 7, 7, 7]), fmt(2, [5, 5, 6, 6, 3]),
        fmt(5, [2 ** 26 + 1, 2 ** 26, 3, 2 ** 25 + 1, 0]),
    ]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            hi = rng.choice([8, 64, 1000, 10**8])
            k = rng.randint(1, n)
            tests.append(fmt(k, [rng.randint(0, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt(50000, [rng.randint(0, 10**8) for _ in range(N)]))
    tests.append(fmt(N, [rng.randint(0, 10**8) for _ in range(N)]))
    tests.append(fmt(1, [rng.randint(0, 255) for _ in range(N)]))
    tests.append(fmt(77777, [rng.choice([0, 1, 2 ** 26 + 1, 2 ** 26 + 2 ** 13, 10**8, 3, 99999999]) for _ in range(N)]))
    return tests
